// Some portions generated by Co-Pilot
"use client";

import { useState } from "react";
import { useTranslations } from "next-intl";
import { FaDocker } from "react-icons/fa";
import { FiCheckCircle, FiChevronDown, FiX } from "react-icons/fi";
import platformSupportData from "@/data/supported-platforms.json";

export default function PlatformMatrix() {
  const t = useTranslations("ModernPages.platforms");
  const tFilters = useTranslations("Temurin.Releases.ReleaseFilters");
  const [openPlatform, setOpenPlatform] = useState<number | null>(null);
  const versions = Array.from(
    new Set(
      platformSupportData.platforms.flatMap((platform) =>
        platform.distros.flatMap((distro) => Object.keys(distro.versions)),
      ),
    ),
  ).sort((a, b) => Number(a) - Number(b));

  const renderFootnote = (text: string) =>
    text.split(/(https?:\/\/[^\s]+)/g).map((part, index) =>
      /^https?:\/\//.test(part) ? (
        <a
          key={index}
          href={part}
          target="_blank"
          rel="noopener noreferrer"
          className="break-words text-[#ff91b7] underline underline-offset-4"
        >
          {part}
        </a>
      ) : (
        part
      ),
    );

  return (
    <section className="mx-auto max-w-7xl px-6 py-10 sm:px-8 sm:py-12">
      <p className="mb-5 text-sm leading-relaxed text-grey">{t("intro")}</p>
      <ul className="mb-6 flex list-none flex-wrap gap-x-6 gap-y-3 p-0 text-sm text-grey">
        <li className="flex items-center gap-2">
          <FiCheckCircle className="text-emerald-400" aria-hidden="true" />
          {t("supported")}
        </li>
        <li className="flex items-center gap-2">
          <FaDocker className="text-blue-300" aria-hidden="true" />
          {t("docker")}
        </li>
        <li className="flex items-center gap-2">
          <FiX aria-hidden="true" />
          {t("unsupported")}
        </li>
      </ul>
      <div className="overflow-hidden rounded-2xl border border-white/10 bg-white/[0.025]">
        {platformSupportData.platforms.map((platform, index) => (
          <div
            key={platform.category}
            className="border-b border-white/10 last:border-b-0"
          >
            <h2 className="m-0">
              <button
                type="button"
                aria-expanded={openPlatform === index}
                aria-controls={`platform-${index}`}
                onClick={() =>
                  setOpenPlatform(openPlatform === index ? null : index)
                }
                className="flex w-full items-center justify-between gap-4 px-5 py-5 text-left text-lg font-semibold hover:bg-white/5 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-pink sm:px-6"
              >
                {platform.category}
                <FiChevronDown
                  aria-hidden="true"
                  className={`shrink-0 text-[#ff91b7] ${openPlatform === index ? "rotate-180" : ""}`}
                />
              </button>
            </h2>
            <div id={`platform-${index}`} hidden={openPlatform !== index}>
              {openPlatform === index && (
                <div className="px-5 pb-5 sm:px-6 sm:pb-6">
                  {platform.footnotes && (
                    <div className="mb-4 space-y-2 rounded-xl border border-pink/15 bg-pink/5 p-4 text-sm leading-relaxed text-grey">
                      {platform.footnotes.map((footnote) => (
                        <p key={footnote} className="m-0">
                          {renderFootnote(footnote)}
                        </p>
                      ))}
                    </div>
                  )}
                  <div
                    className="relative overflow-x-auto rounded-xl border border-white/10"
                    tabIndex={0}
                    role="region"
                    aria-label={platform.category}
                  >
                    <table className="w-full min-w-[640px] border-collapse text-sm">
                      <caption className="sr-only">
                        {platform.category} — {t("title")}
                      </caption>
                      <thead className="bg-[#1c1040] text-grey">
                        <tr>
                          <th
                            scope="col"
                            className="px-4 py-3 text-left font-medium"
                          >
                            {tFilters("operating-system")}
                          </th>
                          {versions.map((version) => (
                            <th
                              key={version}
                              scope="col"
                              className="px-4 py-3 text-center font-medium whitespace-nowrap"
                            >
                              JDK {version}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {platform.distros.map((distro) => (
                          <tr
                            key={distro.name}
                            className="border-t border-white/10 even:bg-white/[0.02]"
                          >
                            <th
                              scope="row"
                              className="px-4 py-4 text-left font-medium text-white"
                            >
                              {distro.name}
                            </th>
                            {versions.map((version) => {
                              const info = (
                                distro.versions as Record<
                                  string,
                                  { supported: boolean; docker: boolean }
                                >
                              )[version];
                              return (
                                <td key={version} className="px-4 py-4">
                                  <div className="flex items-center justify-center gap-2">
                                    {info?.supported ? (
                                      <FiCheckCircle
                                        className="text-emerald-400"
                                        aria-hidden="true"
                                      />
                                    ) : (
                                      <FiX
                                        className="text-grey"
                                        aria-hidden="true"
                                      />
                                    )}
                                    <span className="sr-only">
                                      {info?.supported
                                        ? t("supported")
                                        : t("unsupported")}
                                    </span>
                                    {info?.docker && (
                                      <>
                                        <FaDocker
                                          className="text-blue-300"
                                          aria-hidden="true"
                                        />
                                        <span className="sr-only">
                                          , {t("docker")}
                                        </span>
                                      </>
                                    )}
                                  </div>
                                </td>
                              );
                            })}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
